    private static func decode(_ data: String) -> [String: String] {
        var out: [String: String] = [:]
        for line in data.split(separator: "\n", omittingEmptySubsequences: true) {
            guard let tab = line.firstIndex(of: "\t") else { continue }
            var scalars: [Unicode.Scalar] = []
            for part in line[line.startIndex..<tab].split(separator: "-") {
                if let value = UInt32(part, radix: 16),
                   let scalar = Unicode.Scalar(value) {
                    scalars.append(scalar)
                }
            }
            guard !scalars.isEmpty else { continue }
            out[String(String.UnicodeScalarView(scalars))]
                = String(line[line.index(after: tab)...])
        }
        return out
    }
